  err(`Stage: ${failure.stage}\nExit code: ${failure.exitCode}\nCommand/detail: ${failure.command}\n`);
  err(`Full log: ${logPath}\n`);
  fs.writeFileSync(failurePath,summary);
  await closeLog();
  process.exitCode=failure.exitCode||1;
}

