  }
  const foldedPath=relative.normalize('NFC').toLowerCase();
  assert.ok(!folded.has(foldedPath),`case-insensitive path collision: ${folded.get(foldedPath)} <> ${relative}`);
  folded.set(foldedPath,relative);

