      return j.result ?? j;
    });
    this.temperatureStoreInFlight=task;
    void task.finally(()=>{if(this.temperatureStoreInFlight===task)this.temperatureStoreInFlight=undefined}).catch(()=>{});
    return task;
  }
  resolveUrl(value?:string){
