  async upload(file:File,onProgress?:(percent:number)=>void,externalSignal?:AbortSignal):Promise<string>{
    if(file.size>100*1024*1024)throw new Error('G-code превышает лимит 100 MiB');
    if(file.size===0)throw new Error('G-code пуст');
    if(this.uploadInFlight)throw new Error('На этот принтер уже загружается G-code');
    if(externalSignal?.aborted)throw new RequestCancelledError('Загрузка отменена');
    const controller=new AbortController();
    const externalAbort=()=>controller.abort(externalSignal?.reason);
    externalSignal?.addEventListener('abort',externalAbort,{once:true});
    this.uploadController=controller;
    const task=this.runFileTransfer(async signal=>{
      const ensureActive=()=>{if(signal.aborted)throw new RequestCancelledError('Загрузка отменена пользователем')};
      ensureActive();
      onProgress?.(1);
      const expectedSha256=await blobSha256(file);
      ensureActive();
      onProgress?.(3);
      const started=await secureInvoke<NativeUploadBegin>('transactional_upload_begin',{
        ...this.uploadTarget(),
        filename:file.name,
        fileSize:file.size,
        expectedSha256,
      });
      this.activeUploadId=started.uploadId;
      if(started.completedPath){
        this.uploadedHashes.set(started.completedPath,expectedSha256);
        this.uploadedFiles.set(started.completedPath,file);
        this.activeUploadId=undefined;
        onProgress?.(100);
        return started.completedPath;
      }
      const chunkSize=Math.max(64*1024,Math.min(512*1024,Math.trunc(started.chunkSize)||512*1024));
      let offset=Math.max(0,Math.min(file.size,Math.trunc(started.receivedSize)||0)),finished=false;
      if(offset>0)onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
      try{
        while(offset<file.size){
          ensureActive();
          const end=Math.min(file.size,offset+chunkSize);
          const data=Array.from(new Uint8Array(await file.slice(offset,end).arrayBuffer()));
          ensureActive();
          const received=await secureInvoke<number>('transactional_upload_chunk',{uploadId:started.uploadId,offset,data});
          if(received!==end)throw new Error('Staging-журнал подтвердил неверный размер блока G-code');
          offset=end;
          onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
        }
        ensureActive();
        onProgress?.(95);
        const result=await secureInvoke<NativeUploadFinish>('transactional_upload_finish',{uploadId:started.uploadId});
        finished=true;
        this.uploadedHashes.set(result.path,result.sha256);
        this.uploadedFiles.set(result.path,file);
        while(this.uploadedHashes.size>32)this.uploadedHashes.delete(this.uploadedHashes.keys().next().value as string);
        while(this.uploadedFiles.size>8)this.uploadedFiles.delete(this.uploadedFiles.keys().next().value as string);
        this.invalidateFileCaches(result.path);
        onProgress?.(100);
        return result.path;
      }finally{
        if(this.activeUploadId===started.uploadId)this.activeUploadId=undefined;
        // Transport errors preserve the staged file for resume. Only an
        // explicit user cancellation destroys the resumable transaction.
        if(!finished&&signal.aborted)await secureInvoke<boolean>('transactional_upload_abort',{uploadId:started.uploadId}).catch(error=>{diagnosticWarning('moonraker.upload.abort',error,{printerId:this.config.id,operation:'upload.abort'});return false});
      }
    },controller.signal,'upload.gcode');
    this.uploadInFlight=task;
    try{return await task}
    finally{
      externalSignal?.removeEventListener('abort',externalAbort);
      if(this.uploadInFlight===task)this.uploadInFlight=undefined;
      if(this.uploadController===controller)this.uploadController=undefined;
    }
  }
  cancelUpload(){if(!this.uploadController)return false;this.uploadController.abort('Загрузка отменена пользователем');return true}
  uploadActive(){return!!this.uploadController}
  uploadedSha256(filename:string){return this.uploadedHashes.get(filename)}
  uploadedFile(filename:string){return this.uploadedFiles.get(filename)}
}

export type PrinterLightTarget = {kind:'creality'}|{object:string;name:string;kind:'pin'|'led';scale:number}|{kind:'macro';onCommand:string;offCommand:string};
export type PrinterLightState = {supported:boolean;on?:boolean;detail?:string;target?:string};

// Only explicitly named chamber lights qualify. Never probe arbitrary output
// pins (fans, heaters and other actuators can also be output_pin objects).
const lightNames=['case_light','LED','led','chamber_light','chamber_led','light','lights','caselight','light_pin','LED_pin','led_pin','lighting','chamberlight','chamberlight_pin'];
export function discoverPrinterLight(objects:string[]):PrinterLightTarget|undefined{
  for(const name of lightNames)for(const prefix of ['output_pin','led','neopixel','dotstar','pwm_cycle_time']){
    const object=objects.find(item=>item.toLowerCase()===`${prefix} ${name}`.toLowerCase());
    if(object)return {object,name:object.slice(prefix.length+1),kind:prefix==='output_pin'||prefix==='pwm_cycle_time'?'pin':'led',scale:1};
  }
  for(const base of ['LIGHT','LIGHTS','LED','CASE_LIGHT','CHAMBER_LIGHT']){
    const onCommand=`${base}_ON`,offCommand=`${base}_OFF`;
    if(objects.includes(`gcode_macro ${onCommand}`)&&objects.includes(`gcode_macro ${offCommand}`))return {kind:'macro',onCommand,offCommand};
  }
}
export function printerLightCommand(target:PrinterLightTarget,on:boolean){
  if(target.kind==='creality')throw new Error('Подсветка Creality управляется штатным LAN-каналом, не G-code');
  if(target.kind==='macro')return on?target.onCommand:target.offCommand;
  if(!/^[A-Za-z0-9_]+$/.test(target.name))throw new Error('Недопустимое имя подсветки');
  if(target.kind==='pin')return `SET_PIN PIN=${target.name} VALUE=${on?target.scale:0}`;
  const value=on?1:0;
  return `SET_LED LED=${target.name} RED=${value} GREEN=${value} BLUE=${value} WHITE=${value} SYNC=0`;
}
export function printerLightState(target:PrinterLightTarget,status:Record<string,any>):PrinterLightState{
  if(target.kind==='creality')return {supported:false};
  if(target.kind==='macro')return {supported:true};
  const row=status[target.object];
  if(target.kind==='pin'){
    const scale=Number(status.configfile?.settings?.[target.object]?.scale??status.configfile?.config?.[target.object]?.scale??target.scale);
    if(Number.isFinite(scale)&&scale>0&&scale<=1_000_000)target.scale=scale;
    const raw=row?.value;
    const value=typeof raw==='boolean'?Number(raw):typeof raw==='number'?raw:typeof raw==='string'&&/^\d+(?:\.\d+)?$/.test(raw.trim())?Number(raw):NaN;
    return {supported:true,...(Number.isFinite(value)?{on:value>0}: {})};
  }
  const colors=row?.color_data;
  if(!Array.isArray(colors)||!colors.length||!colors.every(row=>Array.isArray(row)&&row.length>=3&&row.every(v=>typeof v==='number'&&Number.isFinite(v))))return {supported:true};
  return {supported:true,on:colors.some(row=>row.some((v:number)=>v>0))};
}

//! The stock Creality K1 light endpoint. This protocol exposes only a binary
//! chamber light; it is deliberately separate from Moonraker RPC and G-code.

use super::{
    websocket_handshake_path_bound, websocket_read_frame_bounded, websocket_write_frame, HttpTarget,
};
use std::{
    io::BufReader,
    net::TcpStream,
    time::{Duration, Instant},
};

const OPERATION_TIMEOUT: Duration = Duration::from_secs(6);
const MAX_LIGHT_MESSAGE: usize = 64 * 1024;
const READ_LIGHT: &[u8] = br#"{"method":"get","params":{"ReqPrinterPara":1}}"#;
const LIGHT_ON: &[u8] = br#"{"method":"set","params":{"lightSw":1}}"#;
const LIGHT_OFF: &[u8] = br#"{"method":"set","params":{"lightSw":0}}"#;

pub(crate) fn execute(target: &HttpTarget, on: Option<bool>) -> Result<bool, String> {
    execute_with_timeout(target, on, OPERATION_TIMEOUT)
}

fn execute_with_timeout(
    target: &HttpTarget,
    on: Option<bool>,
    timeout: Duration,
) -> Result<bool, String> {
    let deadline = Instant::now() + timeout.min(OPERATION_TIMEOUT);
    let mut reader = websocket_handshake_path_bound(target, None, timeout, None, "/", Some(deadline))?;
    let mut messages = LightMessages::default();
    write(&mut reader, 0x1, READ_LIGHT, deadline)?;
    // Consume a real initial sample before writing. No previous poll or UI
    // value can acknowledge a command sent on this new socket.
    let baseline = read_light(&mut reader, &mut messages, deadline, None)?;
    let Some(desired) = on else {
        return Ok(baseline);
    };
    discard_prewrite_messages(&mut reader, &mut messages, deadline)?;
    // There is exactly one state-changing frame. A failed readback never
    // retries the write or sends a G-code/macro fallback.
    write(&mut reader, 0x1, if desired { LIGHT_ON } else { LIGHT_OFF }, deadline)?;
    write(&mut reader, 0x1, READ_LIGHT, deadline)?;
    read_light(&mut reader, &mut messages, deadline, Some(desired))
}

fn write(
    reader: &mut BufReader<TcpStream>,
    opcode: u8,
    payload: &[u8],
    deadline: Instant,
) -> Result<(), String> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Err("Не удалось подтвердить состояние подсветки: время ожидания истекло".into());
    }
    reader.get_mut().set_write_timeout(Some(remaining)).map_err(|error| error.to_string())?;
    websocket_write_frame(reader.get_mut(), opcode, payload)
}

#[derive(Default)]
struct LightMessages {
    payload: Vec<u8>,
    fragmented: bool,
}

#[derive(Debug, PartialEq, Eq)]
enum LightMessage {
    State(bool),
    Heartbeat,
    Other,
}

fn parse_message(payload: &[u8]) -> Result<LightMessage, String> {
    // Some firmware emits a literal heartbeat acknowledgement, not JSON.
    if payload == b"ok" {
        return Ok(LightMessage::Other);
    }
    let value: serde_json::Value = serde_json::from_slice(payload)
        .map_err(|_| "Принтер вернул некорректное сообщение подсветки")?;
    let object = value.as_object().ok_or("Принтер вернул некорректное сообщение подсветки")?;
    if object.get("ModeCode").and_then(|value| value.as_str()) == Some("heart_beat") {
        return Ok(LightMessage::Heartbeat);
    }
    match object.get("lightSw") {
        None => Ok(LightMessage::Other),
        Some(value) => match value.as_u64() {
            Some(0) => Ok(LightMessage::State(false)),
            Some(1) => Ok(LightMessage::State(true)),
            _ => Err("Принтер вернул недопустимое состояние подсветки".into()),
        },
    }
}

impl LightMessages {
    fn next(
        &mut self,
        reader: &mut BufReader<TcpStream>,
        deadline: Instant,
    ) -> Result<LightMessage, String> {
        loop {
            let (fin, opcode, payload) = websocket_read_frame_bounded(reader, deadline, MAX_LIGHT_MESSAGE)?;
            match opcode {
                0x0 => {
                    if !self.fragmented {
                        return Err("Unexpected Creality WebSocket continuation frame".into());
                    }
                    if payload.len() > MAX_LIGHT_MESSAGE.saturating_sub(self.payload.len()) {
                        return Err("Creality light message exceeds the size limit".into());
                    }
                    self.payload.extend_from_slice(&payload);
                    if !fin {
                        continue;
                    }
                    self.fragmented = false;
                }
                0x1 => {
                    if self.fragmented {
                        return Err("Overlapping Creality WebSocket messages".into());
                    }
                    self.payload = payload;
                    if !fin {
                        self.fragmented = true;
                        continue;
                    }
                }
                0x8 => return Err("Принтер закрыл соединение подсветки до подтверждения".into()),
                0x9 => {
                    write(reader, 0xA, &payload, deadline)?;
                    return Ok(LightMessage::Other);
                }
                0xA => return Ok(LightMessage::Other),
                _ => return Err("Unsupported Creality light WebSocket frame".into()),
            }
            let message = parse_message(&self.payload)?;
            self.payload.clear();
            if message == LightMessage::Heartbeat {
                write(reader, 0x1, b"ok", deadline)?;
                return Ok(LightMessage::Other);
            }
            return Ok(message);
        }
    }
}

fn read_light(
    reader: &mut BufReader<TcpStream>,
    messages: &mut LightMessages,
    deadline: Instant,
    expected: Option<bool>,
) -> Result<bool, String> {
    loop {
        if let LightMessage::State(state) = messages.next(reader, deadline)? {
            if expected.is_none_or(|expected| state == expected) {
                return Ok(state);
            }
        }
    }
}

fn discard_prewrite_messages(
    reader: &mut BufReader<TcpStream>,
    messages: &mut LightMessages,
    deadline: Instant,
) -> Result<(), String> {
    // BufReader may have read initial telemetry beyond the first state.
    // Drain it and any already readable socket bytes before the single write.
    for _ in 0..64 {
        let pending = if reader.buffer().is_empty() && !messages.fragmented {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                return Err("Creality light prewrite timeout".into());
            }
            reader.get_mut().set_read_timeout(Some(remaining.min(Duration::from_millis(10))))
                .map_err(|error| error.to_string())?;
            let mut byte = [0_u8; 1];
            match reader.get_ref().peek(&mut byte) {
                Ok(0) => return Err("Принтер закрыл соединение подсветки".into()),
                Ok(_) => true,
                Err(error) if matches!(error.kind(), std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut) => false,
                Err(error) => return Err(format!("Creality light read failed: {error}")),
            }
        } else {
            true
        };
        if !pending {
            return Ok(());
        }
        let _ = messages.next(reader, deadline)?;
    }
    Err("Creality light initial telemetry exceeds the limit".into())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{io::{BufRead, Read, Write}, net::TcpListener, thread};

    fn server_frame(stream: &mut TcpStream, fin: bool, opcode: u8, payload: &[u8]) {
        assert!(payload.len() <= 125);
        stream.write_all(&[(if fin { 0x80 } else { 0 }) | opcode, payload.len() as u8]).unwrap();
        stream.write_all(payload).unwrap();
    }

    fn client_frame(stream: &mut BufReader<TcpStream>) -> (u8, Vec<u8>) {
        let mut head = [0; 2];
        stream.read_exact(&mut head).unwrap();
        assert_eq!(head[0] & 0x80, 0x80);
        assert_eq!(head[1] & 0x80, 0x80, "client frame must be masked");
        assert!(head[1] & 0x7f < 126);
        let mut mask = [0; 4];
        stream.read_exact(&mut mask).unwrap();
        let mut body = vec![0; (head[1] & 0x7f) as usize];
        stream.read_exact(&mut body).unwrap();
        for (index, byte) in body.iter_mut().enumerate() { *byte ^= mask[index % 4]; }
        (head[0] & 0x0f, body)
    }

    fn serve<F>(handler: F) -> (HttpTarget, thread::JoinHandle<()>)
    where F: FnOnce(BufReader<TcpStream>) + Send + 'static {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let socket = listener.local_addr().unwrap();
        let thread = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            stream.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
            let mut reader = BufReader::new(stream);
            let mut first = String::new();
            reader.read_line(&mut first).unwrap();
            assert_eq!(first, "GET / HTTP/1.1\r\n");
            let mut key = None;
            loop {
                let mut line = String::new(); reader.read_line(&mut line).unwrap();
                assert!(!line.to_ascii_lowercase().starts_with("x-api-key:"));
                if line == "\r\n" { break; }
                if let Some(value) = line.strip_prefix("Sec-WebSocket-Key:") { key = Some(value.trim().to_owned()); }
            }
            let accepted = super::super::websocket_accept_key(&key.unwrap());
            write!(reader.get_mut(), "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {accepted}\r\n\r\n").unwrap();
            handler(reader);
        });
        (HttpTarget { authority: socket.to_string(), socket }, thread)
    }

    #[test]
    fn creality_light_parser_accepts_only_binary_numeric_root_state() {
        assert_eq!(parse_message(br#"{"lightSw":0}"#).unwrap(), LightMessage::State(false));
        assert_eq!(parse_message(br#"{"lightSw":1,"err":6}"#).unwrap(), LightMessage::State(true));
        for invalid in [br#"{"lightSw":true}"#.as_slice(), br#"{"lightSw":"1"}"#, br#"{"lightSw":2}"#, br#"{"lightSw":-1}"#, br#"{"lightSw":1.0}"#, br#"{"lightSw":null}"#] { assert!(parse_message(invalid).is_err()); }
        assert_eq!(parse_message(br#"{"params":{"lightSw":1}}"#).unwrap(), LightMessage::Other);
        assert_eq!(parse_message(b"ok").unwrap(), LightMessage::Other);
        assert_eq!(parse_message(br#"{"result":"ok"}"#).unwrap(), LightMessage::Other);
    }

    #[test]
    fn creality_light_poll_uses_fixed_path_and_real_state() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":1}"#);
        });
        assert!(execute(&target, None).unwrap()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_write_discards_prewrite_and_requires_later_matching_state() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            // A queued matching state must not acknowledge the later write.
            let mut initial = Vec::new();
            for payload in [br#"{"lightSw":1}"#.as_slice(), br#"{"lightSw":0}"#] {
                initial.extend_from_slice(&[0x81, payload.len() as u8]); initial.extend_from_slice(payload);
            }
            reader.get_mut().write_all(&initial).unwrap();
            assert_eq!(client_frame(&mut reader), (1, LIGHT_OFF.to_vec()));
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"result":"ok"}"#);
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":1}"#);
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":0}"#);
        });
        assert!(!execute(&target, Some(false)).unwrap()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_ack_without_readback_fails_without_command_replay() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":0}"#);
            assert_eq!(client_frame(&mut reader), (1, LIGHT_ON.to_vec()));
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, b"ok");
            thread::sleep(Duration::from_millis(350));
            let mut extra = [0; 1];
            assert_eq!(reader.read(&mut extra).unwrap(), 0, "no command replay after timeout");
        });
        assert!(execute_with_timeout(&target, Some(true), Duration::from_millis(250)).is_err()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_does_not_write_when_initial_state_is_missing() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"nozzleTemp":25}"#);
            thread::sleep(Duration::from_millis(200));
            let mut extra = [0; 1]; assert_eq!(reader.read(&mut extra).unwrap(), 0);
        });
        assert!(execute_with_timeout(&target, Some(true), Duration::from_millis(150)).is_err()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_supports_ping_heartbeat_and_fragmented_state() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 9, b"ping");
            assert_eq!(client_frame(&mut reader), (10, b"ping".to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"ModeCode":"heart_beat"}"#);
            assert_eq!(client_frame(&mut reader), (1, b"ok".to_vec()));
            server_frame(reader.get_mut(), false, 1, br#"{"light"#);
            server_frame(reader.get_mut(), true, 0, br#"Sw":1}"#);
        });
        assert!(execute(&target, None).unwrap()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_matching_initial_state_is_not_write_confirmation() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":1}"#);
            assert_eq!(client_frame(&mut reader), (1, LIGHT_ON.to_vec()));
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            server_frame(reader.get_mut(), true, 1, br#"{"lightSw":0}"#);
            thread::sleep(Duration::from_millis(250));
        });
        assert!(execute_with_timeout(&target, Some(true), Duration::from_millis(180)).is_err()); worker.join().unwrap();
    }

    #[test]
    fn creality_light_rejects_malformed_and_oversize_frames() {
        let frames: &[(&[u8], &str)] = &[
            (&[0x81, 0x80, 0, 0, 0, 0], "masked"),
            (&[0xc1, 0], "extension"),
            (&[0x80, 0], "continuation"),
            (&[0x09, 0], "control"),
            (&[0x89, 126, 0, 126], "control"),
            (&[0x81, 126, 0, 1], "canonical"),
            (&[0x81, 127, 0, 0, 0, 0, 0, 1, 0, 1], "size limit"),
            (&[0x82, 0], "Unsupported"),
            (&[0x01, 1, b'{', 0x81, 0], "Overlapping"),
        ];
        for &(frame, expected) in frames {
            let frame = frame.to_vec();
            let (target, worker) = serve(move |mut reader| {
                assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
                reader.get_mut().write_all(&frame).unwrap();
            });
            let error = execute(&target, None).unwrap_err();
            assert!(error.contains(expected), "{expected}: {error}");
            worker.join().unwrap();
        }
    }

    #[test]
    fn creality_light_absolute_deadline_stops_trickled_payload() {
        let (target, worker) = serve(|mut reader| {
            assert_eq!(client_frame(&mut reader), (1, READ_LIGHT.to_vec()));
            reader.get_mut().write_all(&[0x81, 100]).unwrap();
            for _ in 0..100 {
                if reader.get_mut().write_all(b" ").is_err() { break; }
                thread::sleep(Duration::from_millis(20));
            }
        });
        let start = Instant::now();
        assert!(execute_with_timeout(&target, None, Duration::from_millis(150)).is_err());
        assert!(start.elapsed() < Duration::from_secs(1));
        worker.join().unwrap();
    }

    #[test]
    fn creality_light_absolute_deadline_stops_trickled_upgrade() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let socket = listener.local_addr().unwrap();
        let worker = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            for _ in 0..100 {
                if stream.write_all(b"H").is_err() { break; }
                thread::sleep(Duration::from_millis(20));
            }
        });
        let target = HttpTarget { authority: socket.to_string(), socket };
        let start = Instant::now();
        assert!(execute_with_timeout(&target, None, Duration::from_millis(150)).is_err());
        assert!(start.elapsed() < Duration::from_secs(1));
        worker.join().unwrap();
    }

}

