//! Bounded, dependency-free Moonraker HTTP/WebSocket protocol implementation.
//! Keeping wire parsing outside the Tauri assembly root makes the security
//! boundary independently testable and prevents UI command wiring from
//! becoming coupled to socket details.

use super::*;
use socket2::{Domain, Protocol, SockAddr, Socket, Type};

pub(crate) fn connect_tcp_stream(
    target: SocketAddr,
    timeout: Duration,
    bind_ip: Option<IpAddr>,
) -> Result<TcpStream, String> {
    let timeout = bounded_connect_timeout(if timeout.is_zero() {
        Duration::from_millis(1)
    } else {
        timeout
    });
    let Some(bind_ip) = bind_ip else {
        return TcpStream::connect_timeout(&target, timeout)
            .map_err(|error| format!("Moonraker connect failed: {error}"));
    };
    if !matches!(
        (bind_ip, target.ip()),
        (IpAddr::V4(_), IpAddr::V4(_)) | (IpAddr::V6(_), IpAddr::V6(_))
    ) {
        return Err("Moonraker bind failed: семейства локального и целевого адресов различаются".into());
    }
    let socket = Socket::new(
        Domain::for_address(target),
        Type::STREAM,
        Some(Protocol::TCP),
    )
    .map_err(|error| format!("Moonraker socket failed: {error}"))?;
    let source_address = match (bind_ip, target) {
        (IpAddr::V6(source), SocketAddr::V6(destination)) => SocketAddr::V6(
            std::net::SocketAddrV6::new(source, 0, 0, destination.scope_id()),
        ),
        (source, _) => SocketAddr::new(source, 0),
    };
    let source = SockAddr::from(source_address);
    socket
        .bind(&source)
        .map_err(|error| format!("Moonraker bind failed for {bind_ip}: {error}"))?;
    socket
        .connect_timeout(&SockAddr::from(target), timeout)
        .map_err(|error| format!("Moonraker connect failed via {bind_ip}: {error}"))?;
    Ok(socket.into())
}

pub(crate) fn is_safe_ip(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(value) => {
            let octets = value.octets();
            value.is_loopback()
                || octets[0] == 10
                || (octets[0] == 172 && (16..=31).contains(&octets[1]))
                || (octets[0] == 192 && octets[1] == 168)
                || (octets[0] == 169 && octets[1] == 254)
        }
        IpAddr::V6(value) => {
            let segments = value.segments();
            value.is_loopback()
                || (segments[0] & 0xfe00) == 0xfc00
                || (segments[0] & 0xffc0) == 0xfe80
        }
    }
}

pub(crate) fn parse_target(host: &str, default_port: u16) -> Result<HttpTarget, String> {
    let trimmed = host.trim();
    if trimmed.is_empty() || trimmed.len() > 256 || trimmed.chars().any(char::is_control) {
        return Err("Недопустимый адрес Moonraker".into());
    }
    // Preserve the numeric interface scope required by IPv6 link-local
    // targets. url::Url cannot represent this Windows-friendly form.
    if !trimmed.contains("://") && trimmed.starts_with('[') {
        let close = trimmed
            .find(']')
            .ok_or("Недопустимый IPv6-адрес Moonraker")?;
        let inside = &trimmed[1..close];
        let suffix = &trimmed[close + 1..];
        let port = if suffix.is_empty() {
            default_port
        } else {
            suffix
                .strip_prefix(':')
                .ok_or("Недопустимый IPv6-адрес Moonraker")?
                .parse::<u16>()
                .map_err(|_| "Недопустимый порт Moonraker")?
        };
        if port == 0 {
            return Err("Недопустимый порт".into());
        }
        let (address, scope_id) = match inside.rsplit_once('%') {
            Some((address, scope)) => {
                let scope_id = scope
                    .parse::<u32>()
                    .map_err(|_| "IPv6 link-local требует числовой scope ID")?;
                (address, scope_id)
            }
            None => (inside, 0),
        };
        let ip = address
            .parse::<std::net::Ipv6Addr>()
            .map_err(|_| "Недопустимый IPv6-адрес Moonraker")?;
        if !is_safe_ip(IpAddr::V6(ip)) {
            return Err("Разрешены только loopback, link-local и частные IP-адреса".into());
        }
        if ip.is_unicast_link_local() && scope_id == 0 {
            return Err("IPv6 link-local требует scope ID интерфейса".into());
        }
        let authority = if scope_id == 0 {
            format!("[{ip}]:{port}")
        } else {
            format!("[{ip}%{scope_id}]:{port}")
        };
        return Ok(HttpTarget {
            authority,
            socket: SocketAddr::V6(std::net::SocketAddrV6::new(ip, port, 0, scope_id)),
        });
    }
    let candidate = if trimmed.contains("://") {
        trimmed.to_string()
    } else {
        format!("http://{trimmed}")
    };
    let url = Url::parse(&candidate).map_err(|_| "Недопустимый адрес Moonraker")?;
    if url.scheme() != "http"
        || !url.username().is_empty()
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
        || !matches!(url.path(), "" | "/")
    {
        return Err("Используйте локальный HTTP-адрес в формате IP:порт".into());
    }
    let port = url.port().unwrap_or(default_port);
    if port == 0 {
        return Err("Недопустимый порт".into());
    }
    let host_text = url.host_str().ok_or("В адресе Moonraker отсутствует IP или имя")?;
    let (authority, socket) = if let Ok(ip) = host_text.parse::<IpAddr>() {
        if !is_safe_ip(ip) {
            return Err("Разрешены только loopback, link-local и частные IP-адреса".into());
        }
        let authority = match ip {
            IpAddr::V4(_) => format!("{ip}:{port}"),
            IpAddr::V6(_) => format!("[{ip}]:{port}"),
        };
        (authority, SocketAddr::new(ip, port))
    } else {
        let hostname = host_text.trim_end_matches('.').to_ascii_lowercase();
        let local_suffix = !hostname.contains('.')
            || hostname.ends_with(".local")
            || hostname.ends_with(".lan")
            || hostname.ends_with(".home")
            || hostname.ends_with(".internal");
        let valid_labels = !hostname.is_empty()
            && hostname.len() <= 253
            && hostname.split('.').all(|label| {
                !label.is_empty()
                    && label.len() <= 63
                    && !label.starts_with('-')
                    && !label.ends_with('-')
                    && label
                        .bytes()
                        .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
            });
        if !local_suffix || !valid_labels {
            return Err("Разрешены только локальные имена (.local/.lan/.home/.internal)".into());
        }
        let socket = (hostname.as_str(), port)
            .to_socket_addrs()
            .map_err(|_| "Локальное имя принтера не разрешилось в IP-адрес")?
            .find(|value| {
                is_safe_ip(value.ip())
                    && !matches!(value, SocketAddr::V6(ipv6) if ipv6.ip().is_unicast_link_local() && ipv6.scope_id() == 0)
            })
            .ok_or("Локальное имя не указывает на адрес вашей локальной сети")?;
        (format!("{hostname}:{port}"), socket)
    };
    Ok(HttpTarget {
        authority,
        socket,
    })
}

pub(crate) fn moonraker_default_port(value: Option<u16>) -> Result<u16, String> {
    match value.unwrap_or(7125) {
        port @ (80 | 7125) => Ok(port),
        _ => Err("Недопустимый резервный порт Moonraker".into()),
    }
}

pub(crate) fn base64_encode(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let first = chunk[0];
        let second = chunk.get(1).copied().unwrap_or(0);
        let third = chunk.get(2).copied().unwrap_or(0);
        output.push(TABLE[(first >> 2) as usize] as char);
        output.push(TABLE[(((first & 0x03) << 4) | (second >> 4)) as usize] as char);
        if chunk.len() > 1 {
            output.push(TABLE[(((second & 0x0f) << 2) | (third >> 6)) as usize] as char);
        } else {
            output.push('=');
        }
        if chunk.len() > 2 {
            output.push(TABLE[(third & 0x3f) as usize] as char);
        } else {
            output.push('=');
        }
    }
    output
}

// RFC 6455 requires SHA-1 only for validating the WebSocket upgrade.  It is
// not used for passwords, signatures, or any other security decision.
pub(crate) fn sha1_digest(input: &[u8]) -> [u8; 20] {
    let bit_length = (input.len() as u64).wrapping_mul(8);
    let mut padded = input.to_vec();
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_length.to_be_bytes());

    let mut h0 = 0x6745_2301_u32;
    let mut h1 = 0xefcd_ab89_u32;
    let mut h2 = 0x98ba_dcfe_u32;
    let mut h3 = 0x1032_5476_u32;
    let mut h4 = 0xc3d2_e1f0_u32;
    for chunk in padded.as_chunks::<64>().0 {
        let mut words = [0_u32; 80];
        for (index, word) in words.iter_mut().take(16).enumerate() {
            let offset = index * 4;
            *word = u32::from_be_bytes([
                chunk[offset],
                chunk[offset + 1],
                chunk[offset + 2],
                chunk[offset + 3],
            ]);
        }
        for index in 16..80 {
            words[index] =
                (words[index - 3] ^ words[index - 8] ^ words[index - 14] ^ words[index - 16])
                    .rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h0, h1, h2, h3, h4);
        for (index, word) in words.iter().enumerate() {
            let (function, constant) = match index {
                0..=19 => ((b & c) | ((!b) & d), 0x5a82_7999),
                20..=39 => (b ^ c ^ d, 0x6ed9_eba1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8f1b_bcdc),
                _ => (b ^ c ^ d, 0xca62_c1d6),
            };
            let next = a
                .rotate_left(5)
                .wrapping_add(function)
                .wrapping_add(e)
                .wrapping_add(constant)
                .wrapping_add(*word);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = next;
        }
        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }
    let mut output = [0_u8; 20];
    for (index, word) in [h0, h1, h2, h3, h4].iter().enumerate() {
        output[index * 4..index * 4 + 4].copy_from_slice(&word.to_be_bytes());
    }
    output
}

pub(crate) fn websocket_accept_key(client_key: &str) -> String {
    let mut source = String::with_capacity(client_key.len() + 36);
    source.push_str(client_key);
    source.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
    base64_encode(&sha1_digest(source.as_bytes()))
}

pub(crate) fn websocket_header_token(value: &str, expected: &str) -> bool {
    value
        .split(',')
        .any(|token| token.trim().eq_ignore_ascii_case(expected))
}

pub(crate) fn websocket_handshake_bound(
    target: &HttpTarget,
    api_key: Option<&str>,
    timeout: Duration,
    bind_ip: Option<IpAddr>,
) -> Result<BufReader<TcpStream>, String> {
    websocket_handshake_path_bound(target, api_key, timeout, bind_ip, "/websocket", None)
}

// The ordinary Moonraker wrapper above preserves its existing request and
// timeout behavior. The fixed Creality endpoint uses an absolute deadline.
pub(crate) fn websocket_handshake_path_bound(
    target: &HttpTarget,
    api_key: Option<&str>,
    timeout: Duration,
    bind_ip: Option<IpAddr>,
    path: &str,
    deadline: Option<Instant>,
) -> Result<BufReader<TcpStream>, String> {
    if !matches!(path, "/" | "/websocket") {
        return Err("Unsupported fixed WebSocket path".into());
    }
    if let Some(key) = api_key {
        validate_header_value(key, 512)?;
    }
    let io_timeout = if timeout.is_zero() {
        Duration::from_millis(1)
    } else {
        timeout
    };
    let mut stream = connect_tcp_stream(target.socket, io_timeout, bind_ip)
        .map_err(|error| format!("WebSocket connect failed: {error}"))?;
    stream
        .set_read_timeout(Some(io_timeout))
        .map_err(|error| error.to_string())?;
    stream
        .set_write_timeout(Some(io_timeout.min(Duration::from_secs(5))))
        .map_err(|error| error.to_string())?;

    let mut nonce = [0_u8; 16];
    getrandom(&mut nonce).map_err(|error| format!("WebSocket nonce failed: {error}"))?;
    let client_key = base64_encode(&nonce);
    let mut request = format!(
        "GET {path} HTTP/1.1\r\nHost: {}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {client_key}\r\nSec-WebSocket-Version: 13\r\n",
        target.authority
    );
    if let Some(key) = api_key.filter(|value| !value.is_empty()) {
        request.push_str(&format!("X-Api-Key: {key}\r\n"));
    }
    request.push_str("\r\n");
    if let Some(deadline) = deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err("WebSocket upgrade timeout".into());
        }
        stream.set_write_timeout(Some(remaining)).map_err(|error| error.to_string())?;
    }
    stream
        .write_all(request.as_bytes())
        .map_err(|error| format!("WebSocket upgrade write failed: {error}"))?;

    let mut reader = BufReader::new(stream);
    let mut total = 0_usize;
    let mut lines = Vec::new();
    loop {
        let mut raw = Vec::new();
        let read = if let Some(deadline) = deadline {
            loop {
                let mut byte = [0_u8; 1];
                websocket_read_exact_until(&mut reader, &mut byte, deadline)?;
                raw.push(byte[0]);
                if raw.len() > 8 * 1024 {
                    return Err("WebSocket upgrade headers are too large".into());
                }
                if byte[0] == b'\n' {
                    break raw.len();
                }
            }
        } else {
            reader
                .read_until(b'\n', &mut raw)
                .map_err(|error| format!("WebSocket upgrade read failed: {error}"))?
        };
        if read == 0 {
            return Err("WebSocket upgrade response was truncated".into());
        }
        total = total.saturating_add(read);
        if total > 16 * 1024 || raw.len() > 8 * 1024 {
            return Err("WebSocket upgrade headers are too large".into());
        }
        if !raw.ends_with(b"\r\n") {
            return Err("Invalid WebSocket upgrade header".into());
        }
        raw.truncate(raw.len() - 2);
        if raw.is_empty() {
            break;
        }
        lines.push(String::from_utf8(raw).map_err(|_| "Invalid WebSocket upgrade encoding")?);
    }
    let status_line = lines.first().ok_or("WebSocket upgrade status is missing")?;
    let mut status = status_line.split_whitespace();
    if status.next() != Some("HTTP/1.1") || status.next() != Some("101") {
        return Err(format!("WebSocket upgrade rejected: {status_line}"));
    }
    let mut headers = HashMap::<String, String>::new();
    for line in lines.iter().skip(1) {
        if line.starts_with(' ') || line.starts_with('\t') {
            return Err("Folded WebSocket headers are forbidden".into());
        }
        let (name, value) = line
            .split_once(':')
            .ok_or("Invalid WebSocket upgrade header")?;
        if name.is_empty()
            || !name
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        {
            return Err("Invalid WebSocket upgrade header name".into());
        }
        let key = name.to_ascii_lowercase();
        if headers.insert(key, value.trim().to_string()).is_some() {
            return Err("Duplicate WebSocket upgrade header".into());
        }
    }
    if !headers
        .get("upgrade")
        .is_some_and(|value| websocket_header_token(value, "websocket"))
        || !headers
            .get("connection")
            .is_some_and(|value| websocket_header_token(value, "upgrade"))
    {
        return Err("Server did not confirm the WebSocket upgrade".into());
    }
    let expected = websocket_accept_key(&client_key);
    let accepted = headers
        .get("sec-websocket-accept")
        .ok_or("WebSocket accept header is missing")?;
    if accepted.len() != expected.len()
        || !bool::from(accepted.as_bytes().ct_eq(expected.as_bytes()))
    {
        return Err("WebSocket accept key is invalid".into());
    }
    Ok(reader)
}

pub(crate) fn websocket_write_frame(
    stream: &mut TcpStream,
    opcode: u8,
    payload: &[u8],
) -> Result<(), String> {
    if payload.len() > MAX_JSON_RESPONSE {
        return Err("WebSocket message is too large".into());
    }
    let mut header = Vec::with_capacity(14);
    header.push(0x80 | (opcode & 0x0f));
    match payload.len() {
        length @ 0..=125 => header.push(0x80 | length as u8),
        length @ 126..=65_535 => {
            header.push(0x80 | 126);
            header.extend_from_slice(&(length as u16).to_be_bytes());
        }
        length => {
            header.push(0x80 | 127);
            header.extend_from_slice(&(length as u64).to_be_bytes());
        }
    }
    let mut mask = [0_u8; 4];
    getrandom(&mut mask).map_err(|error| format!("WebSocket mask failed: {error}"))?;
    header.extend_from_slice(&mask);
    stream
        .write_all(&header)
        .map_err(|error| format!("WebSocket frame write failed: {error}"))?;
    let masked: Vec<u8> = payload
        .iter()
        .enumerate()
        .map(|(index, byte)| *byte ^ mask[index % 4])
        .collect();
    stream
        .write_all(&masked)
        .map_err(|error| format!("WebSocket payload write failed: {error}"))
}

pub(crate) fn websocket_read_exact(
    reader: &mut BufReader<TcpStream>,
    output: &mut [u8],
    deadline: Instant,
) -> Result<(), String> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Err("WebSocket response timeout".into());
    }
    reader
        .get_mut()
        .set_read_timeout(Some(remaining))
        .map_err(|error| error.to_string())?;
    reader
        .read_exact(output)
        .map_err(|error| format!("WebSocket response failed: {error}"))
}

pub(crate) fn websocket_read_frame(
    reader: &mut BufReader<TcpStream>,
    deadline: Instant,
) -> Result<(bool, u8, Vec<u8>), String> {
    websocket_read_frame_inner(reader, deadline, MAX_JSON_RESPONSE, false)
}

pub(crate) fn websocket_read_frame_bounded(
    reader: &mut BufReader<TcpStream>,
    deadline: Instant,
    max_payload: usize,
) -> Result<(bool, u8, Vec<u8>), String> {
    websocket_read_frame_inner(reader, deadline, max_payload, true)
}

fn websocket_read_exact_until(
    reader: &mut BufReader<TcpStream>,
    mut output: &mut [u8],
    deadline: Instant,
) -> Result<(), String> {
    while !output.is_empty() {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err("WebSocket response timeout".into());
        }
        reader.get_mut().set_read_timeout(Some(remaining)).map_err(|error| error.to_string())?;
        let read = match reader.read(output) {
            Ok(0) => return Err("WebSocket response was truncated".into()),
            Ok(read) => read,
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(error) => return Err(format!("WebSocket response failed: {error}")),
        };
        output = &mut output[read..];
    }
    Ok(())
}

fn websocket_read_frame_inner(
    reader: &mut BufReader<TcpStream>,
    deadline: Instant,
    max_payload: usize,
    absolute_deadline: bool,
) -> Result<(bool, u8, Vec<u8>), String> {
    let read_exact = if absolute_deadline {
        websocket_read_exact_until
    } else {
        websocket_read_exact
    };
    let mut head = [0_u8; 2];
    read_exact(reader, &mut head, deadline)?;
    if head[0] & 0x70 != 0 {
        return Err("Unsupported WebSocket extension bits".into());
    }
    let fin = head[0] & 0x80 != 0;
    let opcode = head[0] & 0x0f;
    if head[1] & 0x80 != 0 {
        return Err("Moonraker sent an invalid masked server frame".into());
    }
    let mut length = (head[1] & 0x7f) as u64;
    if length == 126 {
        let mut extended = [0_u8; 2];
        read_exact(reader, &mut extended, deadline)?;
        length = u16::from_be_bytes(extended) as u64;
        if absolute_deadline && length < 126 {
            return Err("Non-canonical WebSocket message length".into());
        }
    } else if length == 127 {
        let mut extended = [0_u8; 8];
        read_exact(reader, &mut extended, deadline)?;
        length = u64::from_be_bytes(extended);
        if absolute_deadline && length < 65_536 {
            return Err("Non-canonical WebSocket message length".into());
        }
        if length & (1_u64 << 63) != 0 {
            return Err("Invalid WebSocket message length".into());
        }
    }
    if opcode >= 0x8 && (!fin || length > 125) {
        return Err("Invalid WebSocket control frame".into());
    }
    if length > max_payload as u64 {
        return Err("WebSocket response exceeds the size limit".into());
    }
    let mut payload = vec![0_u8; length as usize];
    read_exact(reader, &mut payload, deadline)?;
    Ok((fin, opcode, payload))
}

pub(crate) fn websocket_read_rpc_response(
    reader: &mut BufReader<TcpStream>,
    expected_id: u64,
    deadline: Instant,
) -> Result<serde_json::Value, String> {
    let mut message = Vec::new();
    let mut fragmented = false;
    loop {
        let (fin, opcode, payload) = websocket_read_frame(reader, deadline)?;
        match opcode {
            0x0 => {
                if !fragmented {
                    return Err("Unexpected WebSocket continuation frame".into());
                }
                if payload.len() > MAX_JSON_RESPONSE.saturating_sub(message.len()) {
                    return Err("WebSocket response exceeds the size limit".into());
                }
                message.extend_from_slice(&payload);
                if !fin {
                    continue;
                }
                fragmented = false;
            }
            0x1 => {
                if fragmented {
                    return Err("Overlapping WebSocket messages".into());
                }
                message = payload;
                if !fin {
                    fragmented = true;
                    continue;
                }
            }
            0x8 => return Err("Moonraker closed the WebSocket connection".into()),
            0x9 => {
                websocket_write_frame(reader.get_mut(), 0xA, &payload)?;
                continue;
            }
            0xA => continue,
            0x2 => return Err("Moonraker returned an unsupported binary WebSocket frame".into()),
            _ => return Err("Moonraker returned an unsupported WebSocket frame".into()),
        }
        let json: serde_json::Value = serde_json::from_slice(&message)
            .map_err(|error| format!("Moonraker WebSocket JSON error: {error}"))?;
        message.clear();
        if json.get("id").and_then(|value| value.as_u64()) != Some(expected_id) {
            continue;
        }
        if let Some(error) = json.get("error") {
            let message: String = error
                .get("message")
                .and_then(|value| value.as_str())
                .unwrap_or("Moonraker WebSocket RPC error")
                .chars()
                .take(512)
                .collect();
            return Err(format!("MOONRAKER_WS_RPC: {message}"));
        }
        return Ok(json
            .get("result")
            .cloned()
            .unwrap_or(serde_json::Value::Null));
    }
}

pub(crate) fn websocket_rpc_body(
    id: u64,
    method: &str,
    params: Option<&serde_json::Value>,
) -> Result<Vec<u8>, String> {
    let mut request = serde_json::json!({"jsonrpc":"2.0","method":method,"id":id});
    if let Some(value) = params.filter(|value| !value.is_null()) {
        request["params"] = value.clone();
    }
    let body = serde_json::to_vec(&request).map_err(|error| error.to_string())?;
    if body.len() > 512 * 1024 {
        return Err("Параметры Moonraker слишком велики".into());
    }
    Ok(body)
}

pub(crate) fn websocket_send_rpc(
    reader: &mut BufReader<TcpStream>,
    id: u64,
    method: &str,
    params: Option<&serde_json::Value>,
    deadline: Instant,
) -> Result<serde_json::Value, String> {
    let body = websocket_rpc_body(id, method, params)?;
    websocket_write_frame(reader.get_mut(), 0x1, &body)?;
    websocket_read_rpc_response(reader, id, deadline)
}

pub(crate) fn websocket_rpc_blocking(
    host: String,
    api_key: Option<String>,
    method: String,
    params: Option<serde_json::Value>,
    timeout_ms: Option<u64>,
    default_port: u16,
) -> Result<serde_json::Value, String> {
    websocket_rpc_blocking_bound(
        host,
        api_key,
        method,
        params,
        timeout_ms,
        default_port,
        None,
    )
}

pub(crate) fn websocket_rpc_blocking_bound(
    host: String,
    api_key: Option<String>,
    method: String,
    params: Option<serde_json::Value>,
    timeout_ms: Option<u64>,
    default_port: u16,
    bind_ip: Option<IpAddr>,
) -> Result<serde_json::Value, String> {
    let target = parse_target(&host, default_port)?;
    let timeout = bounded_rpc_timeout(timeout_ms);
    let deadline = Instant::now()
        .checked_add(timeout)
        .ok_or("Недопустимый WebSocket тайм-аут")?;
    let mut reader = websocket_handshake_bound(&target, api_key.as_deref(), timeout, bind_ip)?;
    let mut id = 1_u64;
    if let Some(key) = api_key.as_deref().filter(|value| !value.is_empty()) {
        let identify = serde_json::json!({
            "client_name":"Klipper Farm",
            "version":APP_VERSION,
            "type":"desktop",
            "url":"https://github.com/Arksine/moonraker",
            "api_key":key,
        });
        // Queue identify without waiting for its reply.  The response reader
        // below ignores the earlier id and waits for the requested method, so
        // old Creality builds cannot consume the complete call timeout here.
        let identify_body = websocket_rpc_body(id, "server.connection.identify", Some(&identify))?;
        websocket_write_frame(reader.get_mut(), 0x1, &identify_body)?;
        id += 1;
    }
    websocket_send_rpc(&mut reader, id, &method, params.as_ref(), deadline)
}

pub(crate) fn http_host_url(host: &str, port: u16) -> String {
    if host.contains(':') {
        format!("http://[{host}]:{port}")
    } else {
        format!("http://{host}:{port}")
    }
}

pub(crate) fn validate_header_value(value: &str, maximum: usize) -> Result<(), String> {
    if value.len() > maximum
        || value
            .bytes()
            .any(|byte| byte < 0x20 || byte == 0x7f || byte == b'\r' || byte == b'\n')
    {
        return Err("Недопустимое значение HTTP-заголовка".into());
    }
    Ok(())
}

pub(crate) fn header_boundary(raw: &[u8]) -> Option<usize> {
    raw.windows(4).position(|window| window == b"\r\n\r\n")
}

pub(crate) fn decode_chunked_bytes(body: &[u8], maximum: usize) -> Result<Vec<u8>, String> {
    let mut output = Vec::new();
    let mut cursor = 0;
    loop {
        if cursor >= body.len() {
            return Err("Обрезанный chunked-ответ Moonraker".into());
        }
        let line_end = body[cursor..]
            .windows(2)
            .position(|window| window == b"\r\n")
            .map(|position| cursor + position)
            .ok_or("Некорректный chunked-ответ Moonraker")?;
        if line_end.saturating_sub(cursor) > 128 {
            return Err("Слишком длинный заголовок HTTP-чанка".into());
        }
        let line = std::str::from_utf8(&body[cursor..line_end])
            .map_err(|_| "Некорректный размер HTTP-чанка")?;
        let size_text = line.split(';').next().unwrap_or("").trim();
        let size =
            usize::from_str_radix(size_text, 16).map_err(|_| "Некорректный размер HTTP-чанка")?;
        cursor = line_end + 2;
        if size == 0 {
            return Ok(output);
        }
        if size > maximum.saturating_sub(output.len())
            || body.len() < cursor.saturating_add(size + 2)
        {
            return Err("Ответ Moonraker превышает допустимый размер или обрезан".into());
        }
        output.extend_from_slice(&body[cursor..cursor + size]);
        cursor += size;
        if body.get(cursor..cursor + 2) != Some(b"\r\n") {
            return Err("Некорректный разделитель HTTP-чанка".into());
        }
        cursor += 2;
    }
}

pub(crate) fn parse_http_response(raw: &[u8], maximum: usize) -> Result<HttpResponse, String> {
    if kf_moonraker::http_framing::response_boundary(raw, maximum)? == kf_moonraker::http_framing::Boundary::Incomplete {
        return Err("HTTP-ответ Moonraker обрезан".into());
    }
    let boundary = header_boundary(raw).ok_or("Некорректный HTTP-ответ Moonraker")?;
    if boundary > 64 * 1024 {
        return Err("HTTP-заголовки Moonraker слишком велики".into());
    }
    let head = std::str::from_utf8(&raw[..boundary]).map_err(|_| "Некорректные HTTP-заголовки")?;
    let mut lines = head.split("\r\n");
    let status_line = lines.next().ok_or("HTTP-статус отсутствует")?;
    let mut status_parts = status_line.split_whitespace();
    let protocol = status_parts.next().unwrap_or("");
    let status = status_parts
        .next()
        .ok_or("HTTP-статус отсутствует")?
        .parse::<u16>()
        .map_err(|_| "Некорректный HTTP-статус")?;
    if !matches!(protocol, "HTTP/1.0" | "HTTP/1.1") {
        return Err("Неподдерживаемая версия HTTP".into());
    }
    let mut headers = HashMap::<String, String>::new();
    for line in lines {
        if line.starts_with(' ') || line.starts_with('\t') {
            return Err("Переносы HTTP-заголовков запрещены".into());
        }
        let (name, value) = line.split_once(':').ok_or("Некорректный HTTP-заголовок")?;
        if name.is_empty()
            || !name
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        {
            return Err("Некорректное имя HTTP-заголовка".into());
        }
        let key = name.to_ascii_lowercase();
        if headers.insert(key, value.trim().to_string()).is_some() {
            return Err("Повторяющийся HTTP-заголовок".into());
        }
    }
    let encoded = &raw[boundary + 4..];
    let transfer = headers
        .get("transfer-encoding")
        .map(|value| value.to_ascii_lowercase());
    let content_length = headers
        .get("content-length")
        .map(|value| {
            value
                .parse::<usize>()
                .map_err(|_| "Некорректный Content-Length")
        })
        .transpose()?;
    if transfer.is_some() && content_length.is_some() {
        return Err("Конфликтующие границы HTTP-ответа".into());
    }
    let body = if let Some(encoding) = transfer {
        if encoding != "chunked" {
            return Err("Неподдерживаемый Transfer-Encoding".into());
        }
        decode_chunked_bytes(encoded, maximum)?
    } else if let Some(length) = content_length {
        if length > maximum || encoded.len() != length {
            return Err("HTTP-ответ обрезан или превышает допустимый размер".into());
        }
        encoded.to_vec()
    } else {
        if encoded.len() > maximum {
            return Err("HTTP-ответ превышает допустимый размер".into());
        }
        encoded.to_vec()
    };
    Ok(HttpResponse {
        status,
        content_type: headers.get("content-type").cloned(),
        body,
    })
}

pub(crate) fn http_request(
    target: &HttpTarget,
    method: &str,
    path: &str,
    api_key: Option<&str>,
    content_type: Option<&str>,
    body: &[u8],
    maximum_response: usize,
    timeout: Duration,
) -> Result<HttpResponse, String> {
    http_request_bound(
        target,
        method,
        path,
        api_key,
        content_type,
        body,
        maximum_response,
        timeout,
        None,
    )
}

pub(crate) fn http_request_bound(
    target: &HttpTarget,
    method: &str,
    path: &str,
    api_key: Option<&str>,
    content_type: Option<&str>,
    body: &[u8],
    maximum_response: usize,
    timeout: Duration,
    bind_ip: Option<IpAddr>,
) -> Result<HttpResponse, String> {
    if !matches!(method, "GET" | "POST" | "DELETE")
        || !path.starts_with('/')
        || path.starts_with("//")
        || path.len() > 4096
        || path
            .bytes()
            .any(|byte| byte < 0x20 || byte == 0x7f || byte == b'\\')
    {
        return Err("Недопустимый HTTP-запрос".into());
    }
    if body.len() > MAX_UPLOAD + 1024 * 1024 {
        return Err("Тело HTTP-запроса слишком велико".into());
    }
    if let Some(key) = api_key {
        validate_header_value(key, 512)?;
    }
    if let Some(value) = content_type {
        validate_header_value(value, 256)?;
    }
    // The caller's timeout is an upper bound for both connecting and reading.
    // Normal RPC calls retain the three-second connect cap, while discovery can
    // use a much shorter deadline instead of blocking for three seconds per IP.
    let io_timeout = if timeout.is_zero() {
        Duration::from_millis(1)
    } else {
        timeout
    };
    let io_deadline = Instant::now()
        .checked_add(io_timeout)
        .ok_or("Недопустимый сетевой тайм-аут")?;
    let mut stream = connect_tcp_stream(target.socket, io_timeout, bind_ip)?;
    stream
        .set_read_timeout(Some(io_timeout))
        .map_err(|e| e.to_string())?;
    stream
        .set_write_timeout(Some(io_timeout.min(Duration::from_secs(5))))
        .map_err(|e| e.to_string())?;
    let mut headers = format!(
        "{method} {path} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nAccept: application/json, image/*, text/plain\r\n",
        target.authority
    );
    if let Some(key) = api_key.filter(|value| !value.is_empty()) {
        headers.push_str(&format!("X-Api-Key: {key}\r\n"));
    }
    if !body.is_empty() || method == "POST" {
        headers.push_str(&format!("Content-Length: {}\r\n", body.len()));
        if let Some(value) = content_type {
            headers.push_str(&format!("Content-Type: {value}\r\n"));
        }
    }
    headers.push_str("\r\n");
    stream
        .write_all(headers.as_bytes())
        .map_err(|e| e.to_string())?;
    if !body.is_empty() {
        stream.write_all(body).map_err(|e| e.to_string())?;
    }
    let wire_limit = maximum_response.saturating_add(1024 * 1024);
    let mut raw = Vec::new();
    let mut buffer = [0_u8; 16 * 1024];
    loop {
        let remaining = io_deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err("Moonraker response timeout".into());
        }
        stream
            .set_read_timeout(Some(remaining))
            .map_err(|e| e.to_string())?;
        match stream.read(&mut buffer) {
            Ok(0) => break,
            Ok(read) => {
                if raw.len().saturating_add(read) > wire_limit {
                    return Err("HTTP-ответ Moonraker превышает допустимый размер".into());
                }
                raw.extend_from_slice(&buffer[..read]);
                if kf_moonraker::http_framing::response_boundary(&raw, maximum_response)? == kf_moonraker::http_framing::Boundary::Complete { break; }
            }
            Err(error) if matches!(error.kind(), std::io::ErrorKind::Interrupted) => {}
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                return Err("Moonraker response timeout".into())
            }
            Err(error) => return Err(error.to_string()),
        }
    }
    parse_http_response(&raw, maximum_response)
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn http_request_async(
    target: &HttpTarget,
    method: &str,
    path: &str,
    api_key: Option<&str>,
    content_type: Option<&str>,
    body: &[u8],
    maximum_response: usize,
    timeout: Duration,
    cancellation: &kf_moonraker::CancellationToken,
) -> Result<HttpResponse, String> {
    if !matches!(method, "GET" | "POST" | "DELETE")
        || !path.starts_with('/')
        || path.starts_with("//")
        || path.len() > 4_096
        || path
            .bytes()
            .any(|byte| byte < 0x20 || byte == 0x7f || byte == b'\\')
    {
        return Err("Недопустимый HTTP-запрос".into());
    }
    if body.len() > 512 * 1024 {
        return Err("ASYNC_RPC_BODY_TOO_LARGE".into());
    }
    if let Some(key) = api_key {
        validate_header_value(key, 512)?;
    }
    if let Some(value) = content_type {
        validate_header_value(value, 256)?;
    }
    let mut request = format!(
        "{method} {path} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nAccept: application/json, image/*, text/plain\r\n",
        target.authority
    )
    .into_bytes();
    if let Some(key) = api_key.filter(|value| !value.is_empty()) {
        request.extend_from_slice(format!("X-Api-Key: {key}\r\n").as_bytes());
    }
    if !body.is_empty() || method == "POST" {
        request.extend_from_slice(format!("Content-Length: {}\r\n", body.len()).as_bytes());
        if let Some(value) = content_type {
            request.extend_from_slice(format!("Content-Type: {value}\r\n").as_bytes());
        }
    }
    request.extend_from_slice(b"\r\n");
    request.extend_from_slice(body);
    let wire_limit = maximum_response.saturating_add(1024 * 1024);
    let raw =
        kf_moonraker::tcp_round_trip(target.socket, &request, wire_limit, timeout, cancellation)
            .await
            .map_err(|error| match error {
                kf_moonraker::TransportError::Cancelled => "OPERATION_CANCELLED".into(),
                kf_moonraker::TransportError::Deadline => "OPERATION_DEADLINE_EXCEEDED".into(),
                error => format!("MOONRAKER_ASYNC_TRANSPORT: {error}"),
            })?;
    parse_http_response(&raw, maximum_response)
}

pub(crate) fn bounded_connect_timeout(timeout: Duration) -> Duration {
    let timeout = if timeout.is_zero() {
        Duration::from_millis(1)
    } else {
        timeout
    };
    timeout.min(Duration::from_secs(3))
}

